import { FilmIcon } from "lucide-react"
import { ClientEmptyState } from "./client-empty-state"
import { ClipCard } from "./clip-card"
import type { ClientClip } from "./client-clip"
export function ClipsLibrary({
  clips,
  emptyStateTitle,
  onDownload,
  onDuplicate,
  onRemove,
}: {
  clips: ClientClip[]
  emptyStateTitle: string
  onDownload: (clip: ClientClip) => void
  onDuplicate: (clip: ClientClip) => void
  onRemove: (clip: ClientClip) => void
}) {
  if (!clips.length)
    return <ClientEmptyState icon={FilmIcon} title={emptyStateTitle} />
  return (
    <div className="space-y-2 py-6">
      {clips.map((clip) => (
        <ClipCard
          key={clip.id}
          clip={clip}
          onDownload={() => onDownload(clip)}
          onDuplicate={() => onDuplicate(clip)}
          onRemove={() => onRemove(clip)}
        />
      ))}
    </div>
  )
}

import type { LucideIcon } from "lucide-react"

export function ClientEmptyState({ icon: Icon, title, description }: { icon: LucideIcon; title: string; description?: string }) {
  return (
    <div className="flex min-h-80 flex-col items-center justify-center text-center">
      <Icon className="size-5 text-muted-foreground" aria-hidden="true" />
      <p className="mt-3 text-sm font-medium">{title}</p>
      {description ? <p className="mt-1 max-w-sm text-sm text-muted-foreground">{description}</p> : null}
    </div>
  )
}

"use client"

import type { ComponentProps, ReactNode } from "react"
import {
  ArrowDownToLineIcon,
  CopyIcon,
  ExternalLinkIcon,
  RotateCwIcon,
  Trash2Icon,
} from "lucide-react"

import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from "@/components/ui/context-menu"
import { cn } from "@/lib/utils"

type MediaContextMenuProps = {
  children: ReactNode
  className?: string
  triggerProps?: Omit<ComponentProps<"div">, "children" | "className">
  onOpen?: () => void
  openLabel?: string
  onDownload?: () => void
  onDuplicate?: () => void
  duplicateLabel?: string
  onRemove?: () => void
  removeLabel?: string
}

export function MediaContextMenu({
  children,
  className,
  triggerProps,
  onOpen,
  openLabel = "Open",
  onDownload,
  onDuplicate,
  duplicateLabel = "Duplicate",
  onRemove,
  removeLabel = "Remove",
}: MediaContextMenuProps) {
  return (
    <ContextMenu>
      <ContextMenuTrigger
        className={cn("min-w-0", className)}
        {...triggerProps}
      >
        {children}
      </ContextMenuTrigger>
      <ContextMenuContent>
        {onOpen && (
          <ContextMenuItem onClick={onOpen}>
            <ExternalLinkIcon />
            {openLabel}
          </ContextMenuItem>
        )}
        {onDownload && (
          <ContextMenuItem onClick={onDownload}>
            <ArrowDownToLineIcon />
            Download
          </ContextMenuItem>
        )}
        {onDuplicate && (
          <ContextMenuItem onClick={onDuplicate}>
            {duplicateLabel.toLowerCase().includes("reroll") ? (
              <RotateCwIcon />
            ) : (
              <CopyIcon />
            )}
            {duplicateLabel}
          </ContextMenuItem>
        )}
        {onRemove && (
          <>
            <ContextMenuSeparator />
            <ContextMenuItem variant="destructive" onClick={onRemove}>
              <Trash2Icon />
              {removeLabel}
            </ContextMenuItem>
          </>
        )}
      </ContextMenuContent>
    </ContextMenu>
  )
}

export function downloadMedia(url: string, filename: string) {
  const anchor = document.createElement("a")
  anchor.href = url
  anchor.download = filename
  anchor.click()
}
